"""Normalization helpers for Perses Normal Form (PNF)."""

from __future__ import annotations

import copy
from dataclasses import dataclass

from reduction.grammar import Grammar, GrammarRule, RuleType


QUANTIFIER_TYPES = {
    RuleType.KLEENE_STAR,
    RuleType.KLEENE_PLUS,
    RuleType.OPTIONAL,
}


@dataclass
class PNFNormalizer:
    """Normalize a ``Grammar`` into the reduced PNF shape used by the reducers."""

    _counter: int = 0

    def normalize(self, grammar: Grammar) -> Grammar:
        working = copy.deepcopy(grammar)
        self._hoist_nested_rules(working)
        self._remove_unreachable_rules(working)
        self._inline_alias_rules(working)
        self._remove_immediate_recursion(working)
        self._hoist_nested_rules(working)
        self._inline_alias_rules(working)
        self._remove_unreachable_rules(working)
        return working

    def _hoist_nested_rules(self, grammar: Grammar) -> None:
        changed = True
        while changed:
            changed = False
            for rule in list(grammar.rules.values()):
                replacement: list[str | GrammarRule] = []
                for index, symbol in enumerate(rule.symbols):
                    if isinstance(symbol, GrammarRule):
                        name = symbol.name or self._fresh_name(rule.name, f"embedded_{index}")
                        nested = copy.deepcopy(symbol)
                        nested.name = name
                        grammar.rules[name] = nested
                        replacement.append(name)
                        changed = True
                    else:
                        replacement.append(symbol)
                rule.symbols = replacement

    def _remove_unreachable_rules(self, grammar: Grammar) -> None:
        reachable: set[str] = set()
        stack = [grammar.start_symbol]
        while stack:
            name = stack.pop()
            if name in reachable or name not in grammar.rules:
                continue
            reachable.add(name)
            for symbol in grammar.rules[name].symbols:
                if isinstance(symbol, str) and symbol in grammar.rules:
                    stack.append(symbol)
        grammar.rules = {
            name: rule
            for name, rule in grammar.rules.items()
            if name in reachable
        }

    def _inline_alias_rules(self, grammar: Grammar) -> None:
        aliases: dict[str, str] = {}
        for name, rule in list(grammar.rules.items()):
            if name == grammar.start_symbol:
                continue
            if rule.rule_type in QUANTIFIER_TYPES:
                continue
            if len(rule.symbols) != 1:
                continue
            target = rule.symbols[0]
            if isinstance(target, str) and target in grammar.rules:
                aliases[name] = target

        if not aliases:
            return

        for rule in grammar.rules.values():
            updated: list[str | GrammarRule] = []
            for symbol in rule.symbols:
                if isinstance(symbol, str):
                    updated.append(self._resolve_alias(symbol, aliases))
                else:
                    updated.append(symbol)
            rule.symbols = updated

        for alias in aliases:
            grammar.rules.pop(alias, None)

    def _remove_immediate_recursion(self, grammar: Grammar) -> None:
        for name in list(grammar.rules.keys()):
            if name not in grammar.rules:
                continue
            rule = grammar.rules[name]
            if rule.rule_type != RuleType.ALTERNATION:
                continue

            alternatives = [symbol for symbol in rule.symbols if isinstance(symbol, str)]
            left_recursive: list[list[str]] = []
            right_recursive: list[list[str]] = []
            base_alternatives: list[str] = []

            for alternative_name in alternatives:
                alternative = grammar.rules.get(alternative_name)
                if alternative is None:
                    base_alternatives.append(alternative_name)
                    continue
                symbols = [sym for sym in alternative.symbols if isinstance(sym, str)]
                if alternative.rule_type == RuleType.SEQUENCE and symbols and symbols[0] == name:
                    suffix = symbols[1:]
                    if suffix:
                        left_recursive.append(suffix)
                    continue
                if alternative.rule_type == RuleType.SEQUENCE and symbols and symbols[-1] == name:
                    prefix = symbols[:-1]
                    if prefix:
                        right_recursive.append(prefix)
                    continue
                if alternative_name != name:
                    base_alternatives.append(alternative_name)

            if left_recursive and base_alternatives:
                self._rewrite_left_recursion(grammar, name, base_alternatives, left_recursive)
            elif right_recursive and base_alternatives:
                self._rewrite_right_recursion(grammar, name, base_alternatives, right_recursive)

    def _rewrite_left_recursion(
        self,
        grammar: Grammar,
        name: str,
        bases: list[str],
        suffixes: list[list[str]],
    ) -> None:
        base_rule_name = self._wrap_alternatives(grammar, name, "base", bases)
        item_names = [self._ensure_sequence_rule(grammar, name, "left_item", suffix) for suffix in suffixes]
        item_rule_name = self._wrap_alternatives(grammar, name, "left_items", item_names)
        repeat_name = self._fresh_name(name, "tail")
        grammar.add_rule(GrammarRule(repeat_name, RuleType.KLEENE_STAR, [item_rule_name]))
        grammar.rules[name] = GrammarRule(name, RuleType.SEQUENCE, [base_rule_name, repeat_name])

    def _rewrite_right_recursion(
        self,
        grammar: Grammar,
        name: str,
        bases: list[str],
        prefixes: list[list[str]],
    ) -> None:
        item_names = [self._ensure_sequence_rule(grammar, name, "right_item", prefix) for prefix in prefixes]
        item_rule_name = self._wrap_alternatives(grammar, name, "right_items", item_names)
        repeat_name = self._fresh_name(name, "head")
        grammar.add_rule(GrammarRule(repeat_name, RuleType.KLEENE_STAR, [item_rule_name]))
        base_rule_name = self._wrap_alternatives(grammar, name, "base", bases)
        grammar.rules[name] = GrammarRule(name, RuleType.SEQUENCE, [repeat_name, base_rule_name])

    def _wrap_alternatives(
        self,
        grammar: Grammar,
        owner: str,
        suffix: str,
        alternatives: list[str],
    ) -> str:
        if len(alternatives) == 1:
            return alternatives[0]
        rule_name = self._fresh_name(owner, suffix)
        grammar.add_rule(GrammarRule(rule_name, RuleType.ALTERNATION, list(alternatives)))
        return rule_name

    def _ensure_sequence_rule(
        self,
        grammar: Grammar,
        owner: str,
        suffix: str,
        symbols: list[str],
    ) -> str:
        if len(symbols) == 1:
            return symbols[0]
        rule_name = self._fresh_name(owner, suffix)
        grammar.add_rule(GrammarRule(rule_name, RuleType.SEQUENCE, list(symbols)))
        return rule_name

    def _resolve_alias(self, symbol: str, aliases: dict[str, str]) -> str:
        target = symbol
        seen = set()
        while target in aliases and target not in seen:
            seen.add(target)
            target = aliases[target]
        return target

    def _fresh_name(self, owner: str, suffix: str) -> str:
        self._counter += 1
        return f"{owner}_{suffix}_{self._counter}"


def normalize_grammar(grammar: Grammar) -> Grammar:
    """Return a normalized copy of ``grammar``."""
    return PNFNormalizer().normalize(grammar)

"""Perses-style syntax-guided reducer."""

from __future__ import annotations

import heapq
import itertools
import textwrap
from typing import Iterable

from reduction.grammar import Grammar, RuleType
from reduction.parser import Parser
from reduction.property_test import PropertyTester
from reduction.reducer import AbstractReducer
from reduction.tree import NodeType, SparTreeNode


class PersesReducer(AbstractReducer):
    """Syntax-guided reducer over SparTree nodes."""

    def __init__(self, grammar: Grammar):
        self.grammar = grammar
        self.parser = Parser(grammar)

    @property
    def name(self) -> str:
        return "perses"

    def reduce(self, tree: SparTreeNode, tester: PropertyTester) -> SparTreeNode:
        working = tree.clone()
        while True:
            updated = self._reduce_once(working, tester)
            if updated is None or updated.token_count() >= working.token_count():
                return working
            working = updated

    def _reduce_once(self, tree: SparTreeNode, tester: PropertyTester) -> SparTreeNode | None:
        queue = self._build_priority_queue(tree)
        while queue:
            _, _, path = heapq.heappop(queue)
            node = self._get_node(tree, path)
            if node.deleted or node.token_count() == 0:
                continue

            if self._is_quantified_container(node):
                reduced = self._reduce_quantified_children(tree, path, tester)
                if reduced is not None:
                    return reduced

            if node.node_type == NodeType.REGULAR:
                reduced = self._replace_with_compatible_subtree(tree, path, tester)
                if reduced is not None:
                    return reduced
        return None

    def _build_priority_queue(self, tree: SparTreeNode) -> list[tuple[int, int, tuple[int, ...]]]:
        counter = itertools.count()
        queue: list[tuple[int, int, tuple[int, ...]]] = []
        for path, node in self._iter_nodes(tree):
            if node.node_type == NodeType.TOKEN or node.deleted:
                continue
            heapq.heappush(queue, (-node.token_count(), next(counter), path))
        return queue

    def _reduce_quantified_children(
        self,
        tree: SparTreeNode,
        path: tuple[int, ...],
        tester: PropertyTester,
    ) -> SparTreeNode | None:
        working = tree.clone()
        target = self._get_node(working, path)
        minimum_children = self._minimum_children(target)
        active = self._active_child_indexes(target)
        if len(active) <= minimum_children:
            return None

        changed = False
        granularity = 2
        while len(active) > minimum_children:
            partitions = self._split(active, granularity)
            progress = False
            for partition in partitions:
                if len(active) - len(partition) < minimum_children:
                    continue
                candidate = working.clone()
                candidate_target = self._get_node(candidate, path)
                for index in partition:
                    candidate_target.children[index].delete()
                candidate_source = candidate.to_source()
                if tester.test(candidate_source):
                    working = candidate
                    target = self._get_node(working, path)
                    active = self._active_child_indexes(target)
                    granularity = max(granularity - 1, 2)
                    changed = True
                    progress = True
                    break
            if progress:
                continue
            if granularity >= len(active):
                break
            granularity = min(len(active), granularity * 2)

        if not changed:
            return None
        return self.parser.parse(working.to_source())

    def _replace_with_compatible_subtree(
        self,
        tree: SparTreeNode,
        path: tuple[int, ...],
        tester: PropertyTester,
    ) -> SparTreeNode | None:
        node = self._get_node(tree, path)
        if node.token_count() <= 1:
            return None

        source = tree.to_source()
        if not source:
            return None
        source_lines = source.splitlines()
        if not source_lines:
            return None

        line_map = self._output_line_map(tree)
        span = self._line_span(node)
        if span is None or span[0] not in line_map or span[1] not in line_map:
            return None
        start_index = line_map[span[0]]
        end_index = line_map[span[1]]
        target_indent = self._indent_of_line(source_lines[start_index])

        replacements = []
        for candidate_path, candidate in self._iter_nodes(tree):
            if candidate_path == path:
                continue
            if candidate.node_type != NodeType.REGULAR or candidate.deleted:
                continue
            if candidate.rule_name != node.rule_name:
                continue
            if candidate.token_count() >= node.token_count():
                continue
            candidate_source = candidate.to_source().rstrip("\n")
            if not candidate_source:
                continue
            replacements.append((candidate.token_count(), candidate_source))

        replacements.sort(key=lambda item: item[0])
        seen_sources: set[str] = set()
        for _, candidate_source in replacements:
            replacement_text = self._reindent(candidate_source, target_indent)
            if replacement_text in seen_sources:
                continue
            seen_sources.add(replacement_text)
            new_lines = (
                source_lines[:start_index]
                + replacement_text.splitlines()
                + source_lines[end_index + 1:]
            )
            candidate_program = "\n".join(new_lines).rstrip()
            if not candidate_program:
                continue
            candidate_program += "\n"
            if candidate_program == source:
                continue
            if tester.test(candidate_program):
                return self.parser.parse(candidate_program)
        return None

    def _is_quantified_container(self, node: SparTreeNode) -> bool:
        rule = self.grammar.expected_rule(node.rule_name)
        return bool(
            rule
            and rule.rule_type in (RuleType.KLEENE_STAR, RuleType.KLEENE_PLUS)
            and len(node.children) > 1
        )

    def _minimum_children(self, node: SparTreeNode) -> int:
        rule = self.grammar.expected_rule(node.rule_name)
        if rule and rule.rule_type == RuleType.KLEENE_PLUS:
            return 1
        return 0

    def _output_line_map(self, tree: SparTreeNode) -> dict[int, int]:
        line_numbers = sorted({
            token.line
            for token in tree.tokens()
